node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createClient } from './src/client.mjs';
import { delayFor, shouldRetry } from './src/policy.mjs';
const seen = [];
const delays = [];
let generated = 0;
const request = createClient({
  transport: async ({ headers }) => {
    seen.push(headers);
    return { status: seen.length < 3 ? 503 : 200, headers: seen.length === 1 ? { 'Retry-After': '2' } : {} };
  },
  sleep: async ms => delays.push(ms),
  keyFactory: () => `key-${++generated}`,
  maxAttempts: 3,
});
assert.equal((await request({ method: 'POST', url: '/', headers: { accept: 'application/json' } })).status, 200);
assert.equal(generated, 1);
assert.deepEqual(seen.map(headers => headers['idempotency-key']), ['key-1', 'key-1', 'key-1']);
assert.deepEqual(delays, [2000, 200]);
const explicit = [];
const withKey = createClient({ transport: async ({ headers }) => { explicit.push(headers); return { status: 200 }; }, sleep: async () => {}, keyFactory: () => { throw new Error('must not generate'); } });
await withKey({ method: 'POST', url: '/', headers: { 'Idempotency-Key': 'caller-key', accept: 'text/plain' } });
assert.equal(explicit[0]['Idempotency-Key'], 'caller-key');
assert.equal(explicit[0]['idempotency-key'], undefined);
assert.equal(shouldRetry({ status: 599 }), true);
assert.equal(shouldRetry({ status: 600 }), false);
assert.equal(delayFor({ headers: { 'retry-after': '1.5' } }, 2, 100), 1500);
console.log('contract checks passed');
