import { delayFor, shouldRetry } from './policy.mjs';
export function createClient({ transport, sleep, keyFactory, maxAttempts = 3, baseMs = 100 }) {
  return async function request({ method = 'GET', url, headers = {}, body }) {
    const isPost = String(method).toUpperCase() === 'POST';
    const hasIdempotencyKey = Object.keys(headers).some(name => name.toLowerCase() === 'idempotency-key');
    const needsGeneratedKey = isPost && !hasIdempotencyKey;
    const generatedKey = needsGeneratedKey ? keyFactory() : undefined;
    let response;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      const outgoing = { ...headers };
      if (needsGeneratedKey) outgoing['idempotency-key'] = generatedKey;
      response = await transport({ method, url, headers: outgoing, body });
      if (!shouldRetry(response) || attempt === maxAttempts) return response;
      await sleep(delayFor(response, attempt, baseMs));
    }
    return response;
  };
}

patches.before:
export function delayFor(response, attempt, baseMs) {
  const retryAfter = response.headers?.['retry-after'];
  if (retryAfter !== undefined && Number.isFinite(Number(retryAfter))) return Number(retryAfter);
  return baseMs * 2 ** (attempt - 1);
}
export function shouldRetry(response) {
  return response.status === 429 || response.status >= 500;
}

patches.after:
export function delayFor(response, attempt, baseMs) {
  const headers = response.headers;
  const retryAfter = typeof headers?.get === 'function'
    ? headers.get('retry-after')
    : Object.entries(headers ?? {}).find(([name]) => name.toLowerCase() === 'retry-after')?.[1];
  const seconds = typeof retryAfter === 'number'
    ? retryAfter
    : typeof retryAfter === 'string' && retryAfter.trim() !== ''
      ? Number(retryAfter)
      : NaN;
  if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
  return baseMs * 2 ** (attempt - 1);
}
export function shouldRetry(response) {
  return response.status === 429 || (response.status >= 500 && response.status <= 599);
}
